/* prog38_continued_fraction.c
 * Reimplementation of the original binary's behaviour.
 * It reads two decimal integers from the command line and prints the
 * continued‑fraction representation of the rational number num/den.
 *
 * Behaviour (matching the original):
 *   - Too few arguments          → prints "NO_INPUT"
 *   - Invalid integer strings   → prints "BAD_INPUT"
 *   - Denominator == 0          → prints "BAD_INPUT"
 *   - |numerator| > 100000      → prints "OUT_OF_RANGE"
 *   - More than 200 terms       → prints "ERROR"
 *   - Otherwise prints "[a0; a1, a2, ...]" followed by a newline.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <stdbool.h>
#include <inttypes.h>
#include <limits.h>

#define MAX_TERMS 200
#define MAX_ABS_NUM 100000

/* floor division for signed long long (round toward -inf) */
static long long floor_div(long long n, long long d) {
    long long q = n / d;
    long long r = n % d;
    if (r != 0 && ((r < 0) != (d < 0))) {
        q -= 1;
    }
    return q;
}

static bool parse_ll(const char *s, long long *out) {
    char *endptr;
    errno = 0;
    long long v = strtoll(s, &endptr, 10);
    if (errno != 0) return false;          // overflow/underflow
    if (endptr == s) return false;         // no digits
    if (*endptr != '\0') return false;    // extra characters
    *out = v;
    return true;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    long long num, den;
    if (!parse_ll(argv[1], &num) || !parse_ll(argv[2], &den)) {
        puts("BAD_INPUT");
        return 0;
    }

    if (den == 0) {
        puts("BAD_INPUT");
        return 0;
    }

    if (llabs(num) > MAX_ABS_NUM) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long long terms[MAX_TERMS];
    int count = 0;

    long long a = num;
    long long b = den;
    while (b != 0) {
        if (count >= MAX_TERMS) {
            puts("ERROR");
            return 0;
        }
        long long q = floor_div(a, b);
        long long r = a - q * b;
        terms[count++] = q;
        a = b;
        b = r;
    }

    putchar('[');
    if (count > 0) {
        printf("%" PRId64, terms[0]);
        if (count > 1) {
            printf("; %" PRId64, terms[1]);
            for (int i = 2; i < count; ++i) {
                printf(", %" PRId64, terms[i]);
            }
        }
    }
    putchar(']');
    putchar('\n');
    return 0;
}
